/* ---------------------------------------------------------------- email */
function send_mail(string $to, string $subject, string $text): bool {
    $from = setting('support_email');
    $headers = 'From: ' . setting('site_name') . ' <' . $from . ">\r\nReply-To: " . $from . "\r\nContent-Type: text/plain; charset=UTF-8\r\n";
    return @mail($to, '=?UTF-8?B?' . base64_encode($subject) . '?=', $text, $headers, '-f' . $from);
}

/* ---------------------------------------------------------------- markdown-lite for admin-written content */
function sanitize_html(string $html): string {
    // allow a safe subset of tags written in the admin editor
    $html = preg_replace('#<(script|style|iframe|object|embed)[^>]*>.*?</\1>#is', '', $html);
    $html = preg_replace('/\son\w+\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)/i', '', $html);
    $html = preg_replace('/(href|src)\s*=\s*([\'"])\s*javascript:[^\'"]*\2/i', '$1="#"', $html);
    return strip_tags($html, '<p><br><h2><h3><h4><strong><b><em><i><u><a><ul><ol><li><blockquote><img><table><thead><tbody><tr><th><td><figure><figcaption><hr><span><div>');
}


/* ================================================================ product descriptions */

// Kiratora product copy: descriptions (US English) built from each product's own data, plus the Google description
// for product pages. Used on first install, for new Card Bot imports and from Admin â€º Tools.

function d_pick(array $p, array $options, int $salt = 0) {
    return $options[(crc32('kt' . ($p['handle'] ?? '') . $salt) % count($options))];
}
function d_an(string $word): string { return preg_match('/^[aeiou]/i', $word) && !preg_match('/^(uni|one|eu|use)/i', $word) ? 'an' : 'a'; }
function d_list(array $items): string {
    $items = array_values($items);
    if (count($items) < 2) return (string)($items[0] ?? '');
    return implode(', ', array_slice($items, 0, -1)) . ' and ' . end($items);
}
function d_lang(array $p): string {
    return ['Japanese' => 'Japanese', 'Chinese' => 'Simplified Chinese', 'English' => 'English'][$p['language'] ?? 'English'] ?? (string)$p['language'];
}
const PUBLISHERS = ['PokÃ©mon' => 'The PokÃ©mon Company', 'Riftbound' => 'Riot Games', 'Lorcana' => 'Ravensburger', 'One Piece' => 'Bandai', 'Magic: The Gathering' => 'Wizards of the Coast',
    'Dragon Ball' => 'Bandai', 'Gundam' => 'Bandai', 'Digimon' => 'Bandai', 'Yu-Gi-Oh!' => 'Konami', 'Star Wars' => 'Fantasy Flight Games', 'Weiss Schwarz' => 'Bushiroad'];
const GAME_FULL = ['PokÃ©mon' => 'PokÃ©mon TCG', 'Riftbound' => 'Riftbound: League of Legends TCG', 'Lorcana' => 'Disney Lorcana', 'One Piece' => 'One Piece Card Game',
    'Magic: The Gathering' => 'Magic: The Gathering', 'Dragon Ball' => 'Dragon Ball Super Card Game', 'Gundam' => 'Gundam Card Game', 'Digimon' => 'Digimon Card Game',
    'Yu-Gi-Oh!' => 'Yu-Gi-Oh! TCG', 'Star Wars' => 'Star Wars: Unlimited', 'Weiss Schwarz' => 'Weiss Schwarz', 'Naruto' => 'Naruto Kayou card range',
    'K-Pop Demon Hunters' => 'K-Pop Demon Hunters card range', 'Marvel Rivals' => 'Marvel Rivals card range', 'Sports' => 'sports card range'];

// What a PokÃ©mon rarity means, in a sentence or two.
function d_rarity_note(array $p): string {
    $r = (string)$p['rarity'];
    $jp = ($p['language'] ?? '') === 'Japanese';
    return match ($r) {
        'Common', 'Uncommon' => 'Commons and Uncommons make up the bulk of every pack, and no master set is complete without them. Reverse holos, ball-pattern foils and promo prints of these cards can be worth many times the regular version, so check which one you are buying.',
        'Rare' => 'A Rare, marked by one black star, usually takes the rare position in a booster, a notch above the commons.',
        'Holo Rare' => 'A Holo Rare puts holographic foil on the artwork itself, the shine that has made pulls exciting since the very first sets.',
        'Double Rare' => 'Two black stars mean Double Rare: the rarity of regular-art PokÃ©mon ex across the Scarlet & Violet and Mega Evolution eras.',
        'Ultra Rare' => 'Ultra Rares carry edge-to-edge artwork with a textured foil finish you can feel under your thumb.',
        'Super Rare' => 'Super Rare (SR) is how Japanese sets mark their full-art cards, the match for an English Ultra Rare: artwork across the whole card on textured foil.',
        'Illustration Rare' => 'An Illustration Rare places an ordinary PokÃ©mon inside a full-card painting. They are much scarcer than holos and anchor plenty of art-focused collections.',
        'Art Rare' => 'Art Rare (AR) is what Japanese sets call an Illustration Rare: a regular PokÃ©mon shown in a full-card scene, far harder to pull than a holo.',
        'Special Illustration Rare' => 'A Special Illustration Rare is the headline card of its set: one-off full artwork of a PokÃ©mon ex or Supporter, two gold stars in the corner, and one of the scarcest pulls in the box.',
        'Special Art Rare' => 'Special Art Rare (SAR) is the Japanese counterpart of a Special Illustration Rare, the leading art card of a Japanese set and one of its hardest pulls.',
        'Hyper Rare' => 'Hyper Rare means gold: etched gold foil, three gold stars and, in most sets, the hardest card to find in a pack.',
        'Mega Hyper Rare' => 'Mega Hyper Rare tops the rarity ladder of the Mega Evolution series, the scarcest card type in any of its packs.',
        'Secret Rare' => 'Secret Rares carry a number higher than the setâ€™s printed total, placing them beyond the final card of the official list.',
        'Shiny Rare', 'Shiny Holo Rare' => 'Shiny Rares picture the PokÃ©mon in its unusual alternate coloring against a sparkling foil background.',
        'Shiny Ultra Rare' => 'A Shiny Ultra Rare pairs full-card artwork with shiny coloring, which is why they rank among the most chased cards of the shiny sets.',
        'Radiant Rare' => 'Radiant PokÃ©mon arrived in the Sword & Shield era: shiny-colored cards with etched foil, and only one allowed in any deck.',
        'ACE SPEC Rare' => 'An ACE SPEC is a Trainer card so powerful that the rules let each deck include just one.',
        'Amazing Rare' => 'Amazing Rares date from the Sword & Shield era and show the PokÃ©mon bursting out of a rainbow splash of color.',
        'Black White Rare' => 'Black White Rare is the exclusive top rarity created for Black Bolt and White Flare.',
        'Promo' => 'You will not find promos in regular booster packs: they are released through collection boxes, Elite Trainer Boxes, events and special products' . ($jp ? '' : ', and each carries a Black Star Promo number') . '.',
        default => '',
    };
}
function d_finish(array $p): string {
    $v = (string)$p['variant']; $n = (string)$p['card_name'];
    if (str_contains($n, 'Master Ball Pattern') || str_contains($v, 'Master Ball')) return 'Master Ball pattern reverse holo (the rarer of the two patterns)';
    if (str_contains($n, 'Poke Ball Pattern') || str_contains($v, 'Poke Ball')) return 'PokÃ© Ball pattern reverse holo';
    if (preg_match('/Love Ball|Friend Ball|Quick Ball/', $v, $m)) return "{$m[0]} pattern reverse holo";
    if (str_contains($n, 'Cosmos Holofoil')) return 'Cosmos holofoil';
    if (str_starts_with($v, 'Reverse Holofoil')) return 'Reverse holo';
    if ($v === 'Holofoil') return 'Holofoil';
    return '';
}
function d_secret_note(array $p): string {
    if (preg_match('#^(\d+)/(\d+)$#', (string)$p['card_number'], $m) && (int)$m[1] > (int)$m[2] && $p['rarity'] !== 'Secret Rare')
        return " Numbered {$p['card_number']}, it goes past the " . (int)$m[2] . " cards of the set list, so it counts as a secret rare.";
    return '';
}
function d_clean_name(array $p): string {
    $n = trim((string)$p['card_name']);
    $n = trim(preg_replace('/\s*\((Master Ball|Poke Ball) Pattern\)/', '', $n));
    return $n !== '' ? $n : (string)$p['title'];
}
function d_set_link(array $p): string {
    if (empty($p['set_url']) || empty($p['set_name'])) return '';
    return '<a href="' . h($p['set_url']) . '">' . h($p['set_name']) . '</a>';
}
function d_card_page(array $p): string {
    foreach (auto_paths($p) as $path) if (preg_match('#^/cards/(' . implode('|', CARD_NAMES) . ')-pokemon-cards$#', $path, $m))
        return '<a href="' . $path . '">' . ucfirst($m[1]) . ' collection</a>';
    return '';
}
// The most valuable singles we carry from the same set (read from the catalog, so it stays accurate).
function d_chase(array $p, int $n = 3): array {
    static $cache = [];
    if (empty($p['set_url'])) return [];
    if (!isset($cache[$p['set_url']])) {
        $cache[$p['set_url']] = all("SELECT id, handle, card_name, title, card_number FROM products WHERE set_url = ? AND section = 'Single Cards' AND published = 1 AND price_usd IS NOT NULL ORDER BY price_usd DESC LIMIT 12", [$p['set_url']]);
    }
    $out = []; $seen = [];
    foreach ($cache[$p['set_url']] as $r) {
        if ((int)$r['id'] === (int)($p['id'] ?? 0)) continue;
        $nm = trim(preg_replace(['/\s*\((Master Ball|Poke Ball) Pattern\)/', '#^\d+\*?/\d+\s+#'], '', $r['card_name'] ?: $r['title']));
        if (isset($seen[$nm]) || $nm === d_clean_name($p)) continue;
        $seen[$nm] = 1;
        $out[] = '<a href="/products/' . h($r['handle']) . '">' . h($nm . ($r['card_number'] ? ' ' . $r['card_number'] : '')) . '</a>';
        if (count($out) >= $n) break;
    }
    return $out;
}
function d_ship(array $p): string {
    $free = (float)setting('free_shipping_over_usd');
    return d_pick($p, [
        'Packed in Japan and on its way no more than 48 hours after you pay, it travels with full tracking (Japan Post EMS, DHL Express or FedEx), and US delivery usually takes 3â€“6 working days.',
        $free > 0 ? 'It leaves Japan no later than 48 hours after payment, tracked all the way, and Standard shipping costs nothing once the goods pass ' . money_usd($free) . '.'
                  : 'It leaves Japan no later than 48 hours after payment, tracked all the way to your door.',
        'Prices are in US dollars, and a paid order is on its way from Japan at most 48 hours later, with door-to-door tracking.',
        'Expect dispatch from Japan no more than 48 hours after payment with Japan Post EMS, DHL Express or FedEx; Standard delivery to the US normally takes 3â€“6 working days.',
    ], 31);
}
function d_spec(array $rows): string {
    $rows = array_filter($rows, fn($v) => $v !== '' && $v !== null);
    if (!$rows) return '';
    $li = '';
    foreach ($rows as $k => $v) $li .= '<li><strong>' . h($k) . ':</strong> ' . $v . '</li>';
    return '<ul>' . $li . '</ul>';
}
function d_lang_line(array $p): string {
    $lang = $p['language'] ?? 'English';
    if ($lang === 'Japanese') return d_pick($p, [
        'Japanese cards are the same 63 by 88 mm as English cards, so your usual sleeves, toploaders and binder pages fit them perfectly.',
        'Collectors and graders value Japanese printings for their sharp, well-centered print, and they are cut to 63 by 88 mm like any standard card.',
        'Japanese sets normally arrive months before their English versions, at exactly the same card size.',
    ], 33);
    if ($lang === 'Chinese') return 'This is an official Simplified Chinese printing made for the PokÃ©mon TCG in mainland China, a fast-growing corner of the hobby.';
    return d_pick($p, ['This is the English printing, the version found on US store shelves.', 'This English printing is cut to the usual 63 by 88 mm card size.'], 33);
}

/* ------------------------------------------------------------------ singles */
function d_pokemon_single(array $p): array {
    $name = d_clean_name($p); $num = (string)$p['card_number']; $rar = (string)$p['rarity']; $type = (string)$p['card_type'];
    $setName = (string)$p['set_name']; $series = (string)$p['series'];
    $kind = preg_match('/\bEnergy\b/', $name) ? 'Energy card' : (is_trainer_card($p) ? 'Trainer card' : ($type !== '' ? "$type-type PokÃ©mon" : 'PokÃ©mon card'));
    $what = ($rar !== '' ? d_an($rar) . ' ' . h($rar) : 'a') . ' ' . $kind;
    $jumbo = $p['subsection'] === 'Jumbo cards';
    $intro = $jumbo ? '<strong>' . h($name) . '</strong> is a jumbo-size card from a premium collection, made for display rather than play.'
        : d_pick($p, [
            '<strong>' . h($name) . '</strong> is ' . $what . ($setName !== '' ? ' from ' . h($setName) : '') . '.',
            'Looking for <strong>' . h($name) . '</strong>? This is ' . $what . ($num !== '' ? ', card ' . h($num) : '') . ($setName !== '' ? ' of ' . h($setName) : '') . '.',
            '<strong>' . h($name) . '</strong>' . ($num !== '' ? ' (' . h($num) . ')' : '') . ': ' . $what . ($setName !== '' ? ' in the ' . h($setName) . ' set' : '') . '.',
        ], 41);
    $intro .= d_secret_note($p);
    $spec = d_spec([
        'Rarity' => h($rar), 'Number' => h($num), 'Finish' => h(d_finish($p)),
        'Set' => d_set_link($p) . ($series !== '' && $setName !== '' && !str_contains($setName, $series) ? ' (' . h($series) . ')' : ''),
        'Language' => h(d_lang($p)), 'Condition' => 'Ungraded (raw) single',
    ]);
    $chase = d_chase($p);
    $setPage = '<a href="' . h((string)$p['set_url']) . '">' . h($setName) . '</a>';
    $more = '';
    if ($chase) $more = d_pick($p, [
        'Other standouts from this set: ' . d_list($chase) . '. The whole ' . $setPage . ' checklist is priced and sorted by number.',
        'Completing ' . h($setName) . '? ' . d_list($chase) . ' are among its most sought-after cards, and every other card is on the ' . $setPage . ' page.',
        'Also in ' . h($setName) . ': ' . d_list($chase) . '. The full card list, with prices, is on the ' . $setPage . ' page.',
    ], 43);
    $cp = d_card_page($p);
    if ($cp) $more .= ($more ? ' ' : '') . "Want every version of this PokÃ©mon we stock? See our $cp.";
    return array_filter([$intro, $spec, d_rarity_note($p), $more, d_lang_line($p) . ' ' . d_ship($p)]);
}
function d_other_single(array $p): array {
    $game = (string)$p['game']; $full = GAME_FULL[$game] ?? $game; $name = d_clean_name($p);
    $rar = (string)$p['rarity']; $setName = (string)$p['set_name']; $num = (string)$p['card_number'];
    $pub = PUBLISHERS[$game] ?? '';
    $intro = $game === 'Anime promos' ? '<strong>' . h($name) . '</strong> is a promo card released alongside a Japanese anime or manga event, offered here as a single.'
        : '<strong>' . h($name) . '</strong> is ' . (str_ends_with($full, 'range') ? 'a single from the ' . $full : 'a ' . $full . ' single') . ($setName !== '' ? ' from ' . d_set_link($p) : '') . '.';
    $notes = [
        'Lorcana' => ['Enchanted' => 'Enchanted cards are the top chase in Lorcana: borderless full-art foils numbered beyond the end of the set.', 'Legendary' => 'Legendary is the highest standard rarity in Disney Lorcana.', 'Super Rare' => 'In Lorcana, Super Rare ranks just below Legendary.'],
        'Riftbound' => ['Epic' => 'Epic is the highest standard rarity in Riftbound.'],
    ];
    $note = $notes[$game][$rar] ?? '';
    if ($game === 'Riftbound' && str_contains($name, 'Alternate Art')) $note = 'This is the alternate art printing, one of the most collected versions in Riftbound.';
    $spec = d_spec(['Rarity' => strlen($rar) > 3 ? h($rar) : '', 'Number' => h($num), 'Publisher' => h($pub), 'Condition' => 'Ungraded (raw) single']);
    $chase = d_chase($p);
    $more = $chase ? 'More from ' . h($setName) . ': ' . d_list($chase) . '.' : '';
    return array_filter([$intro, $spec, trim($note . ' ' . $more), d_ship($p)]);
}

/* ------------------------------------------------------------------ graded */
const PSA_GRADES = ['10' => 'Gem Mint', '9' => 'Mint', '8' => 'NM-MT (Near Mint-Mint)', '7' => 'NM (Near Mint)', '6' => 'EX-MT (Excellent-Mint)', '5' => 'EX (Excellent)', '4' => 'VG-EX (Very Good-Excellent)', '3' => 'VG (Very Good)', '2' => 'Good', '1' => 'Poor'];
function d_graded(array $p): array {
    $t = (string)$p['title'];
    $grade = preg_match('/\bPSA (10|[1-9](?:\.5)?)\b/', $t, $m) ? $m[1] : null;
    $year = preg_match('/^(\d{4}(?:-\d{2})?)\b/', $t, $y) ? $y[1] : null;
    $card = trim(preg_replace(['/\s*\bPSA (10|[1-9](\.5)?)\b\s*$/', '/^\d{4}(-\d{2})?\s+/', '/\bPokemon\b/'], ['', '', 'PokÃ©mon'], $t));
    $game = (string)$p['game'];
    $intro = '<strong>' . h($card) . '</strong>, ' . ($grade ? 'authenticated and graded by PSA, in its sealed slab.' : 'authenticated and sealed in its grading case.');
    $spec = d_spec(['Game' => $game === 'Sports' ? 'Sports' : h($game), 'Year' => h((string)$year), 'Language' => ($p['language'] ?? '') === 'Japanese' ? 'Japanese' : '',
        'Grade' => $grade ? 'PSA ' . $grade . (isset(PSA_GRADES[$grade]) ? ' ' . PSA_GRADES[$grade] : '') : '']);
    $why = $grade === '10' ? 'PSA 10 is the top of PSAâ€™s scale and demands near-perfect centering, corners, edges and surface, which is why a 10 regularly sells for a multiple of the raw card.'
        : ($grade ? "A PSA $grade on the 1 to 10 scale means an expert has already judged the condition, so you are not relying on photos of a raw card." : 'Its grade is printed on the tamper-evident case.');
    $cert = 'Check the certification number on the label against PSAâ€™s online database to confirm it. The photos show the exact slab you will get.';
    $cp = $game === 'PokÃ©mon' ? d_card_page($p) : '';
    if ($game === 'PokÃ©mon') $cert .= ' Browse more in our <a href="/cards/psa-graded-pokemon-cards">graded PokÃ©mon cards</a>' . ($grade === '10' ? ' and <a href="/cards/psa-10-pokemon-cards">PSA 10</a> pages' : '') . ($cp ? ", or see the $cp" : '') . '.';
    return array_filter([$intro, $spec, $why, $cert, d_ship($p)]);
}

/* ------------------------------------------------------------------ sealed + accessories */
function d_count(array $p): string {
    return preg_match('/\((\d+)\s*(?:ct|count|packs?)\)/i', (string)$p['title'], $m) ? $m[1] : '';
}
function d_sealed(array $p): array {
    $t = (string)$p['title']; $game = (string)$p['game']; $sec = (string)$p['section'];
    $lang = d_lang($p); $setName = (string)$p['set_name']; $full = GAME_FULL[$game] ?? $game; $pub = PUBLISHERS[$game] ?? '';
    $type = match (true) {
        $sec === 'Booster Box Cases' || $sec === 'Cases' || (bool)preg_match('/\bcase\b/i', $t) => 'case',
        $sec === 'Elite Trainer Boxes' || stripos($t, 'elite trainer') !== false => 'etb',
        (bool)preg_match('/hobby box/i', $t) => 'hobby',
        (bool)preg_match('/figur|blind box|plush/i', $t) => 'figure',
        $sec === 'Booster Boxes' || $sec === 'Booster & Hobby Boxes' || (bool)preg_match('/booster box|display/i', $t) => 'box',
        (bool)preg_match('/\bdecks?\b/i', $t) => 'deck',
        $sec === 'Booster Packs' || $sec === 'Packs' || (bool)preg_match('/\bpack\b/i', $t) => 'pack',
        (bool)preg_match('/\btin\b/i', $t) => 'tin',
        (bool)preg_match('/blister/i', $t) => 'blister',
        default => 'set',
    };
    $what = ['case' => 'sealed distributor case', 'etb' => 'Elite Trainer Box', 'hobby' => 'hobby box', 'figure' => 'sealed collectible', 'box' => 'booster box', 'deck' => 'ready-to-play deck', 'pack' => 'booster pack', 'tin' => 'collector tin', 'blister' => 'retail blister', 'set' => 'sealed product'][$type];
    $intro = '<strong>' . h($t) . '</strong> is ' . d_an(($lang !== 'English' ? $lang : '') ?: $what) . ' ' . ($lang !== 'English' ? h($lang) . ' ' : '') . $what . ($setName !== '' ? ' from ' . d_set_link($p) : '') . ', still factory sealed.';
    $about = match ($type) {
        'case' => 'Shops and resellers buy cases to stock up, and this one comes in its original distributor carton.',
        'etb' => 'Each Elite Trainer Box combines booster packs from the set with themed sleeves, dice, condition markers and a sturdy box to store it all' . ($lang === 'Japanese' ? '; the Japanese edition is packed differently from the English one.' : '.'),
        'box' => 'Opening a set pack by pack costs least with a full booster box, and it is also the format collectors most often keep sealed.',
        'hobby' => 'Hobby boxes offer the strongest odds of autographs, memorabilia cards and numbered parallels.',
        'pack' => 'Opening more than a handful? Per pack, a sealed booster box costs less.',
        'deck' => 'Ready to play straight away: an easy introduction to the game, or a low-cost way to pick up the cards inside.',
        'tin' => 'Each tin holds booster packs and a promo card.',
        'figure' => 'Blind boxes stay sealed, so the design inside stays a surprise.',
        default => '',
    };
    if ($game !== 'PokÃ©mon' && $game !== 'Sports' && $pub && $type !== 'hobby') $about = trim($about . ' ' . (str_ends_with($full, 'range') ? 'The ' : '') . "$full comes from $pub.");
    if ($game === 'Sports' && preg_match('/\b(Panini|Topps|Upper Deck|Leaf|Bowman|Donruss)\b/', $t, $b)) $about = trim($about . " Produced by {$b[1]}.");
    $spec = d_spec(['Language' => h($lang), 'Set' => d_set_link($p), 'Units inside' => d_count($p), 'Condition' => 'Factory sealed, never opened or resealed']);
    $chase = $setName ? d_chase($p, 4) : [];
    $hits = $chase ? d_pick($p, ['Top cards in this set include ' . d_list($chase) . ', and each is sold separately as well.', 'Hoping for a big pull? Look for ' . d_list($chase) . ', all of which we also sell as singles.'], 45)
        . ' The full card list is on the <a href="' . h($p['set_url']) . '">' . h($setName) . '</a> page.' : '';
    if ($lang === 'Japanese' && $game === 'PokÃ©mon') $hits = trim($hits . ' ' . d_pick($p, ['Japanese boxes come out months ahead of the English releases, and plenty of US collectors prefer them for the crisper print.', 'Earlier release dates and print quality make Japanese sealed product a favorite with US shops and collectors.'], 47));
    $buy = ($p['price_usd'] !== null && ($p['moq'] ?? null) !== 1 ? 'Anyone can buy at quantity prices, no account needed: the minimum, the case step and each price break are shown above. ' : '') . d_ship($p);
    return array_filter([$intro . ' ' . $about, $spec, $hits, $buy]);
}
function d_accessory(array $p): array {
    $t = '<strong>' . h((string)$p['title']) . '</strong>'; $sub = (string)$p['subsection']; $tt = mb_strtolower((string)$p['title']);
    $lang = ($p['language'] ?? '') === 'Japanese' ? ' A Japanese release, with a design rarely seen in US stores.' : '';
    $s1 = match (true) {
        str_contains($tt, 'sleeve') => "$t: sleeves to protect your cards in a deck or a storage box.$lang Standard size, made for 63 by 88 mm cards such as PokÃ©mon and most other TCGs.",
        (bool)preg_match('/bumper|slab/', $tt) => "$t: a bumper that fits around the edges of a graded slab, protecting it from knocks and scratches and framing it for display.",
        $sub === 'Top loaders & cases' || (bool)preg_match('/top ?loader|one.?touch|magnetic/', $tt) => "$t: a rigid holder for your best cards. Slide in a sleeved card and it stays flat for storage, shipping or display.",
        str_contains($tt, 'binder') => "$t: a binder for storing and displaying your collection, with side-loading pockets that keep cards from sliding out.",
        str_contains($tt, 'deck box') || $sub === 'Deck boxes' => "$t: a deck box to keep a sleeved deck safe on the go.$lang",
        (bool)preg_match('/playmat|dice|coin/', $tt) || $sub === 'Playmats, dice & coins' => "$t: an accessory for game night at the table.$lang",
        default => "$t: an accessory for protecting, storing or displaying your cards.$lang",
    };
    return array_filter([$s1, 'Accessories follow the same open quantity pricing as everything else at ' . h(setting('site_name')) . ', so shops can buy at the lower tiers. ' . d_ship($p)]);
}

function describe_product(array $p): string {
    $sec = (string)$p['section']; $game = (string)$p['game'];
    $paras = match (true) {
        $sec === 'Single Cards' && $game === 'PokÃ©mon' => d_pokemon_single($p),
        $sec === 'Single Cards' => d_other_single($p),
        in_array($sec, ['PSA Graded Cards', 'Graded Cards'], true) => d_graded($p),
        $sec === 'Accessories' => d_accessory($p),
        $sec === 'Collectibles' => ['<strong>' . h($p['title']) . '</strong> belongs to our ' . h($game === 'Other collectibles' ? 'collectibles' : $game) . ' range.', d_ship($p)],
        default => d_sealed($p),
    };
    return implode('', array_map(fn($x) => str_starts_with($x, '<ul') ? $x : '<p>' . trim(preg_replace('/\s+/', ' ', $x)) . '</p>', $paras));
}
function describe_fill(bool $all = false): int {
    $n = 0;
    $pdo = db(); $pdo->beginTransaction();
    $up = $pdo->prepare('UPDATE products SET description = ? WHERE id = ?');
    foreach (q('SELECT * FROM products' . ($all ? '' : ' WHERE desc_auto = 1')) ->fetchAll() as $p) { $up->execute([describe_product($p), $p['id']]); $n++; }
    $pdo->commit();
    return $n;
}

// Google description for a product page, built live so price and stock stay current.
function product_meta_desc(array $p): string {
    if (trim((string)$p['meta_desc']) !== '') return (string)$p['meta_desc'];
    $sec = (string)$p['section'];
    $lad = $p['price_usd'] !== null ? ladder($p) : null;
    $low = $lad && $lad['tiers'] ? (float)end($lad['tiers'])[1] : (float)($p['price_usd'] ?? 0);
    if ($sec === 'Single Cards' && $p['card_name'] !== '') {
        $lead = d_clean_name($p) . ($p['card_number'] ? ' (' . $p['card_number'] . ')' : '') . ($p['rarity'] ? ', ' . $p['rarity'] : '') . ($p['set_name'] ? ', ' . $p['set_name'] : '') . (($p['language'] ?? '') !== 'English' ? ', ' . $p['language'] : '');
    } else $lead = (string)$p['title'];
    $state = !$p['in_stock'] ? 'Currently out of stock' : ($lad ? 'In stock from $' . number_format($low, 2) : 'In stock');
    $tail = " â€” $state. Ships tracked from Japan to the US with " . setting('site_name') . '.';
    $tail2 = " â€” $state, shipped tracked from Japan.";
    foreach ([$lead . $tail, $lead . $tail2] as $s) if (mb_strlen($s) <= 155) return $s;
    return mb_strimwidth($lead, 0, 155 - mb_strlen($tail2) - 1, 'â€¦') . $tail2;
}
// Google title for a product page: the full name, with the shop name when it fits. Long names are reworded shorter
// (no year on slabs, SAR/SIR, nothing written twice) but never cut off, so similar listings keep different titles.
function product_seo_title(array $p): string {
    if (trim((string)$p['seo_title']) !== '') return (string)$p['seo_title'];
    $brand = ' | ' . setting('site_name');
    $t = trim(preg_replace('/\s+/u', ' ', (string)$p['title']));
    if (mb_strlen($t . $brand) <= 60) return $t . $brand;
    $s = seo_shorten($t);
    return mb_strlen($s . $brand) <= 60 ? $s . $brand : $s;
}
function seo_shorten(string $t): string {
    $t = preg_replace('/^(?:19|20)\d\d (?=\S)/', '', $t);                                                  // the year on graded slabs
    $t = preg_replace('/ \((?:GEM MINT|MINT|NM-MT|NM|EX-MT|EX)\)$/', '', $t);                                // "PSA 10 (GEM MINT)": the number says it
    $t = preg_replace('/^Pok[eÃ©]mon TCG:? ?(?:(?:Scarlet & Violet|Sword & Shield|Mega Evolution) ?(?:[â€“â€”-] ?)?)?/u', 'PokÃ©mon ', $t);
    $t = preg_replace('/^(?:Scarlet & Violet|Sword & Shield|Mega Evolution) (?=(?!Base\b)[A-Z][a-z])/u', '', $t);   // the series before a set name
    $t = strtr($t, ['Special Illustration Rare' => 'SIR', 'Special Art Rare' => 'SAR', 'Illustration Rare' => 'IR', 'Alternate Full Art' => 'Alt Full Art',
                    'Alternate Art' => 'Alt Art', 'Simplified Chinese' => 'Chinese', 'Magic: The Gathering' => 'MTG', 'Magic The Gathering' => 'MTG',
                    'Ball Pattern)' => 'Ball)', ' - ' => ' ', ' â€“ ' => ' ', ' â€” ' => ' ']);
    $t = preg_replace('#\b(\d+/\d+)\b(.*) \1\b#u', '$1$2', $t);                                                // a card number written twice
    $t = preg_replace('/\b((?:[\p{L}\p{N}&\'.]+ ){1,4}[\p{L}\p{N}&\'.]+)\b(.*) \1\b/iu', '$1$2', $t);        // a phrase written twice
    return trim(preg_replace('/\s+/u', ' ', $t));
}
// Description HTML as readable plain text for Google: list items and headings end as sentences, blocks are spaced,
// entities decoded once ("box. Set: 30th Celebration." rather than "box.Set: 30th Celebration").
function plain_text(string $html): string {
    $html = preg_replace('#(?<![.!?:;])\s*(</(?:li|h[1-6])>)#i', '.$1', $html);
    $html = preg_replace('#<(?:br|/p|/li|/h[1-6]|/div|/tr|/td|/th|/blockquote|/figcaption)\b[^>]*>#i', '$0 ', $html);
    return trim(preg_replace('/\s+/u', ' ', html_entity_decode(strip_tags($html), ENT_QUOTES | ENT_HTML5, 'UTF-8')));
}

/* ================================================================ database schema */
function schema_sql(): string {
    return <<<'__KTR_SCHEMA__'
PRAGMA journal_mode = WAL;

CREATE TABLE IF NOT EXISTS products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source TEXT NOT NULL DEFAULT 'manual',          -- cardbot | import | manual
  source_id TEXT,
  handle TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  game TEXT NOT NULL DEFAULT 'PokÃ©mon',
  section TEXT NOT NULL,
  subsection TEXT NOT NULL DEFAULT '',
  section_url TEXT NOT NULL DEFAULT '',
  game_url TEXT NOT NULL DEFAULT '',
  set_name TEXT NOT NULL DEFAULT '',
  set_url TEXT NOT NULL DEFAULT '',
  series TEXT NOT NULL DEFAULT '',
  language TEXT NOT NULL DEFAULT 'English',
  card_name TEXT NOT NULL DEFAULT '',
  card_number TEXT NOT NULL DEFAULT '',
  rarity TEXT NOT NULL DEFAULT '',
  card_type TEXT NOT NULL DEFAULT '',
  variant TEXT NOT NULL DEFAULT '',
  sku TEXT NOT NULL DEFAULT '',
  price_usd REAL,                                  -- base price at the minimum quantity
  compare_usd REAL,                                -- optional "was" price
  source_price REAL,
  source_currency TEXT NOT NULL DEFAULT '',
  moq INTEGER,                                     -- NULL = use pricing rules
  step INTEGER,                                    -- NULL = use pricing rules
  breaks TEXT,                                     -- JSON [[qty, price_usd], ...]; NULL = use pricing rules
  in_stock INTEGER NOT NULL DEFAULT 1,
  published INTEGER NOT NULL DEFAULT 1,
  seo_index INTEGER NOT NULL DEFAULT 1,
  featured INTEGER NOT NULL DEFAULT 0,
  also_on TEXT NOT NULL DEFAULT '',                -- extra collection paths, space separated
  image_url TEXT NOT NULL DEFAULT '',
  image_local TEXT NOT NULL DEFAULT '',
  alt_text TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  seo_title TEXT NOT NULL DEFAULT '',
  meta_desc TEXT NOT NULL DEFAULT '',
  desc_auto INTEGER NOT NULL DEFAULT 1,                -- 1 = description written automatically (safe to refresh); 0 = written by hand
  sort_number REAL,                                -- numeric card number for "set order" sorting
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS ix_products_game ON products(game);
CREATE INDEX IF NOT EXISTS ix_products_section ON products(section);
CREATE INDEX IF NOT EXISTS ix_products_set ON products(set_url);
CREATE INDEX IF NOT EXISTS ix_products_stock ON products(published, in_stock);
CREATE INDEX IF NOT EXISTS ix_products_price ON products(price_usd);

-- Every listing page (category, set, game, card page, language) is a collection.
CREATE TABLE IF NOT EXISTS collections (
  path TEXT PRIMARY KEY,
  kind TEXT NOT NULL,              -- shop | section | set | game | game_section | card | language
  title TEXT NOT NULL,
  h1 TEXT NOT NULL DEFAULT '',
  game TEXT NOT NULL DEFAULT '',
  series TEXT NOT NULL DEFAULT '',
  intro TEXT NOT NULL DEFAULT '',  -- HTML shown above the products
  body TEXT NOT NULL DEFAULT '',   -- HTML shown below the products (SEO copy, FAQ)
  seo_title TEXT NOT NULL DEFAULT '',
  meta_desc TEXT NOT NULL DEFAULT '',
  primary_kw TEXT NOT NULL DEFAULT '',
  seo_index INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 100,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS product_paths (
  product_id INTEGER NOT NULL,
  path TEXT NOT NULL,
  PRIMARY KEY (product_id, path)
);
CREATE INDEX IF NOT EXISTS ix_pp_path ON product_paths(path, product_id);

-- Guides, blog posts and info pages.
CREATE TABLE IF NOT EXISTS pages (
  path TEXT PRIMARY KEY,
  type TEXT NOT NULL DEFAULT 'page',   -- page | guide | blog
  title TEXT NOT NULL,
  h1 TEXT NOT NULL DEFAULT '',
  excerpt TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL DEFAULT '',
  seo_title TEXT NOT NULL DEFAULT '',
  meta_desc TEXT NOT NULL DEFAULT '',
  primary_kw TEXT NOT NULL DEFAULT '',
  image TEXT NOT NULL DEFAULT '',
  published INTEGER NOT NULL DEFAULT 1,
  seo_index INTEGER NOT NULL DEFAULT 1,
  published_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT NOT NULL UNIQUE,
  token TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'awaiting_payment',  -- awaiting_payment | paid | shipped | cancelled
  name TEXT NOT NULL, company TEXT NOT NULL DEFAULT '', email TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '',
  country TEXT NOT NULL, address1 TEXT NOT NULL, address2 TEXT NOT NULL DEFAULT '', city TEXT NOT NULL,
  region TEXT NOT NULL DEFAULT '', postcode TEXT NOT NULL DEFAULT '',
  shipping_method TEXT NOT NULL DEFAULT 'standard', payment_method TEXT NOT NULL DEFAULT 'bitcoin',
  currency TEXT NOT NULL DEFAULT 'USD', rate REAL NOT NULL DEFAULT 1,
  subtotal_usd REAL NOT NULL, shipping_usd REAL, total_usd REAL NOT NULL,
  notes TEXT NOT NULL DEFAULT '', admin_notes TEXT NOT NULL DEFAULT '', tracking TEXT NOT NULL DEFAULT '',
  hold_until TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS order_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id INTEGER NOT NULL,
  product_id INTEGER,
  title TEXT NOT NULL, sku TEXT NOT NULL DEFAULT '', handle TEXT NOT NULL DEFAULT '',
  qty INTEGER NOT NULL, unit_usd REAL NOT NULL, line_usd REAL NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_items_order ON order_items(order_id);

CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS redirects (from_path TEXT PRIMARY KEY, to_path TEXT NOT NULL, code INTEGER NOT NULL DEFAULT 301, hits INTEGER NOT NULL DEFAULT 0);
__KTR_SCHEMA__;
}

/* ================================================================ page links */


function rebuild_all_paths(): int {
    $pdo = db();
    $pdo->beginTransaction();
    $pdo->exec('DELETE FROM product_paths');
    $ins = $pdo->prepare('INSERT OR IGNORE INTO product_paths(product_id, path) VALUES(?, ?)');
    $n = 0;
    foreach (q('SELECT * FROM products')->fetchAll() as $p) {
        foreach (product_paths($p) as $path) $ins->execute([$p['id'], $path]);
        $n++;
    }
    $pdo->commit();
    return $n;
}

/* ================================================================ storefront */


// Product counts for menu links (one query per page view).
function menu_counts(): array {
    static $c = null;
    if ($c === null) { $c = []; foreach (all('SELECT path, COUNT(*) n FROM product_paths GROUP BY path') as $r) $c[$r['path']] = (int)$r['n']; }
    return $c;
}
// A featured product for a menu: [image, title, price text, url] or null.
function menu_pick(string $sql, array $args = []): ?array {
    $p = one($sql, $args);
    if (!$p) return null;
    $lad = $p['price_usd'] !== null ? ladder($p) : null;
    return [product_image($p), $p['title'], $lad ? 'From ' . money(end($lad['tiers'])[1]) : '', '/products/' . $p['handle']];
}
