// Bitcoin price in USD for the order page (two public sources; null if both are unreachable)
function btc_usd(): ?float {
    $j = json_decode((string)http_get('https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd', 5), true);
    if (!empty($j['bitcoin']['usd'])) return (float)$j['bitcoin']['usd'];
    $j = json_decode((string)http_get('https://api.coinbase.com/v2/prices/BTC-USD/spot', 5), true);
    return !empty($j['data']['amount']) ? (float)$j['data']['amount'] : null;
}
const COUNTRIES = ['United States', 'Canada', 'United Kingdom', 'Japan', 'Australia', 'New Zealand', 'Germany', 'France', 'Netherlands', 'Belgium', 'Spain', 'Italy', 'Sweden', 'Norway', 'Denmark', 'Finland', 'Ireland', 'Switzerland', 'Austria', 'Poland', 'Portugal', 'Czech Republic', 'Greece', 'Singapore', 'Hong Kong', 'Taiwan', 'South Korea', 'Malaysia', 'Philippines', 'Thailand', 'Indonesia', 'Vietnam', 'United Arab Emirates', 'Saudi Arabia', 'Mexico', 'Brazil', 'Chile', 'South Africa', 'Nigeria', 'Cameroon', 'Other'];
function page_checkout(): void {
    $s = cart_summary();
    if (!$s['lines']) redirect('/cart');
    $errors = []; $d = $_POST;
    if (is_post()) {
        csrf_check();
        foreach (['name' => 'Name', 'email' => 'Email', 'country' => 'Country', 'address1' => 'Address', 'city' => 'City'] as $k => $label) if (trim((string)($d[$k] ?? '')) === '') $errors[$k] = "$label is required.";
        if (!empty($d['email']) && !filter_var($d['email'], FILTER_VALIDATE_EMAIL)) $errors['email'] = 'Enter a valid email.';
        $method = ($d['shipping'] ?? '') === 'express' ? 'express' : 'standard';
        $pay = isset(payment_methods()[$d['payment'] ?? '']) ? $d['payment'] : array_key_first(payment_methods());
        $only = PAYMENT_METHODS[$pay][2];
        if ($only && ($d['country'] ?? '') !== $only) $errors['payment'] = PAYMENT_METHODS[$pay][0] . ' is only for ' . ($only === 'United States' ? 'US' : 'UK') . ' customers. Choose another payment method.';
        if (!empty($d['country']) && !in_array($d['country'], COUNTRIES, true)) $errors['country'] = 'Choose your country from the list.';
        $kg = cart_weight($s['lines']);
        $ship = shipping_cost($s['subtotal'], $method, (string)($d['country'] ?? 'United States'), $kg);
        $total = $s['subtotal'] + $ship;
        if ($total < (float)setting('min_order_usd')) $errors['min'] = 'The minimum order is ' . money((float)setting('min_order_usd')) . ' including shipping.';
        if (!$errors) {
            $code = 'KT-' . strtoupper(substr(bin2hex(random_bytes(4)), 0, 6));
            $token = bin2hex(random_bytes(12));
            db()->beginTransaction();
            q('INSERT INTO orders(code, token, name, company, email, phone, country, address1, address2, city, region, postcode, shipping_method, payment_method, currency, rate, subtotal_usd, shipping_usd, total_usd, notes, hold_until)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', [$code, $token, trim($d['name']), trim($d['company'] ?? ''), trim($d['email']), trim($d['phone'] ?? ''), $d['country'], trim($d['address1']),
               trim($d['address2'] ?? ''), trim($d['city']), trim($d['region'] ?? ''), trim($d['postcode'] ?? ''), $method, $pay, currency(), rates()[currency()] ?? 1, $s['subtotal'], $ship, $total,
               trim($d['notes'] ?? ''), date('Y-m-d H:i:s', time() + 3600 * (int)setting('hold_hours'))]);
            $oid = (int)db()->lastInsertId();
            q('UPDATE orders SET weight_kg = ? WHERE id = ?', [$kg, $oid]);
            if ($pay === 'bitcoin' && ($btcUsd = btc_usd())) q('UPDATE orders SET btc_rate = ?, btc_amount = ? WHERE id = ?', [$btcUsd, number_format($total / $btcUsd, 8, '.', ''), $oid]);
            foreach ($s['lines'] as $l) q('INSERT INTO order_items(order_id, product_id, title, sku, handle, qty, unit_usd, line_usd) VALUES(?,?,?,?,?,?,?,?)', [$oid, $l['p']['id'], $l['p']['title'], $l['p']['sku'], $l['p']['handle'], $l['qty'], $l['unit'], $l['line']]);
            db()->commit();
            $_SESSION['cart'] = [];
            $_SESSION['orders'][] = $code;
            $o = one('SELECT * FROM orders WHERE id = ?', [$oid]);
            $link = setting('site_url') . "/order/$code?k=$token";
            $txt = view('email_order', ['o' => $o, 'items' => all('SELECT * FROM order_items WHERE order_id = ?', [$oid]), 'link' => $link]);
            send_mail($o['email'], "Order $code received â€“ " . setting('site_name'), $txt);
            send_mail(setting('orders_email'), "New order $code (" . money($total, 'USD') . ")", $txt);
            redirect("/order/$code?k=$token");
        }
    }
    $meta = ['title' => 'Checkout | ' . setting('site_name'), 'robots' => 'noindex,nofollow'];
    echo view('layout', ['meta' => $meta, 'content' => view('checkout', compact('s', 'errors', 'd'))]);
}
function page_order(string $code): void {
    start_session();
    $o = one('SELECT * FROM orders WHERE code = ?', [$code]);
    if (!$o || (!hash_equals($o['token'], (string)($_GET['k'] ?? '')) && !in_array($code, $_SESSION['orders'] ?? [], true))) not_found();
    $items = all('SELECT * FROM order_items WHERE order_id = ?', [$o['id']]);
    $meta = ['title' => "Order {$o['code']} | " . setting('site_name'), 'robots' => 'noindex,nofollow'];
    echo view('layout', ['meta' => $meta, 'content' => view('order', compact('o', 'items'))]);
}

