/* ------------------------------------------------------------------ SEO overview, redirects */
function admin_seo(): void {
    $rows = [];
    foreach (all("SELECT path, COALESCE(NULLIF(seo_title,''), title) t, seo_title, meta_desc, primary_kw, seo_index, 'listing' src FROM collections") as $r) $rows[] = $r;
    foreach (all("SELECT path, COALESCE(NULLIF(seo_title,''), title) t, seo_title, meta_desc, primary_kw, seo_index, 'page' src FROM pages WHERE published = 1") as $r) $rows[] = $r;
    $issues = fn($r) => array_filter([$r['seo_title'] === '' ? 'No Google title' : (mb_strlen($r['seo_title']) > 60 ? 'Title too long' : null), $r['meta_desc'] === '' ? 'No description' : (mb_strlen($r['meta_desc']) > 155 ? 'Description too long' : null), $r['primary_kw'] === '' && $r['src'] === 'page' ? 'No keyword' : null]);
    usort($rows, fn($a, $b) => count($issues($b)) <=> count($issues($a)) ?: strcmp($a['path'], $b['path']));
    $prodIdx = (int)val('SELECT COUNT(*) FROM products WHERE published = 1 AND seo_index = 1');
    ob_start(); ?>
<h1>SEO</h1>
<div class="kpis">
  <div class="kpi"><span>Products in Google</span><strong><?= number_format($prodIdx) ?></strong></div>
  <div class="kpi"><span>Pages with issues</span><strong><?= count(array_filter($rows, fn($r) => $issues($r))) ?></strong></div>
  <a class="kpi" href="/sitemap.xml" target="_blank" rel="noopener"><span>Sitemap for Google</span><strong class="small mono">/sitemap.xml â†—</strong></a>
  <a class="kpi" href="/admin/redirects"><span>Redirects</span><strong><?= (int)val('SELECT COUNT(*) FROM redirects') ?></strong></a>
</div>
<div class="card flush"><table class="tbl"><thead><tr><th>Page</th><th>Title in Google</th><th>Chars</th><th>Description</th><th>Issues</th></tr></thead><tbody>
<?php foreach ($rows as $r): $is = $issues($r); $edit = $r['src'] === 'page' ? '/admin/pages/edit?path=' . urlencode($r['path']) : '/admin/collections/edit?path=' . urlencode($r['path']); ?>
<tr><td><a href="<?= h($edit) ?>" class="mono small"><?= h($r['path']) ?></a></td><td class="small"><?= h($r['t']) ?></td><td class="mono small <?= mb_strlen($r['t']) > 60 ? 'amber-text' : '' ?>"><?= mb_strlen($r['t']) ?></td>
<td class="small muted"><?= h(mb_strimwidth($r['meta_desc'], 0, 90, 'â€¦')) ?></td><td><?php foreach ($is as $i): ?><span class="status amber"><?= h($i) ?></span> <?php endforeach ?><?= $is ? '' : '<span class="status green">Good</span>' ?></td></tr>
<?php endforeach ?></tbody></table></div>
<?php echo admin_shell('SEO', ob_get_clean(), 'seo');
}
function admin_redirects(): void {
    if (is_post()) {
        if (!empty($_POST['remove'])) q('DELETE FROM redirects WHERE from_path = ?', [$_POST['remove']]);
        else {
            $from = '/' . trim(parse_url(trim((string)$_POST['from']), PHP_URL_PATH) ?: '', '/'); $to = trim((string)$_POST['to']);
            if ($from !== '/' && $to !== '') q('INSERT OR REPLACE INTO redirects(from_path, to_path, code) VALUES(?, ?, 301)', [$from, $to]);
        }
        flash('Redirects updated.'); redirect('/admin/redirects');
    }
    $rows = all('SELECT * FROM redirects ORDER BY from_path');
    ob_start(); ?>
<h1>Redirects</h1>
<p class="muted">Send visitors and Google from an old address to a new one (301 permanent). Renaming a page here adds one automatically.</p>
<form method="post" class="filters card"><?= csrf_field() ?><input name="from" placeholder="/old-address" required aria-label="Old address"><input name="to" placeholder="/new-address" required aria-label="New address"><button class="btn primary">Add redirect</button></form>
<div class="card flush"><table class="tbl"><thead><tr><th>From</th><th>To</th><th>Visits</th><th></th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="4" class="muted">No redirects yet. Add one when you rename or remove a page, so visitors and Google land on the new address.</td></tr><?php endif ?>
<?php foreach ($rows as $r): ?><tr><td class="mono small"><?= h($r['from_path']) ?></td><td class="mono small"><?= h($r['to_path']) ?></td><td class="mono"><?= (int)$r['hits'] ?></td><td><form method="post"><?= csrf_field() ?><button class="btn ghost small" name="remove" value="<?= h($r['from_path']) ?>">Remove</button></form></td></tr><?php endforeach ?>
</tbody></table></div>
<?php echo admin_shell('Redirects', ob_get_clean(), 'seo');
}

/* ------------------------------------------------------------------ settings */
function admin_settings(): void {
    $msg = '';
    if (is_post()) {
        $a = $_POST['save'] ?? '';
        if ($a === 'rates_live') {
            $json = @file_get_contents('https://open.er-api.com/v6/latest/USD', false, stream_context_create(['http' => ['timeout' => 10]]));
            $d = $json ? json_decode($json, true) : null;
            if (!empty($d['rates'])) {
                $keep = array_keys(rates()); $new = [];
                foreach ($keep as $c) $new[$c] = isset($d['rates'][$c]) ? round((float)$d['rates'][$c], 4) : rates()[$c];
                set_setting('rates', json_encode($new)); set_setting('rates_updated', date('Y-m-d H:i'));
                flash('Exchange rates updated from the live feed.');
            } else flash('Could not reach the rates feed from your server. You can type the rates in instead.');
            redirect('/admin/settings#currency');
        }
        if ($a === 'password') {
            if (!password_verify((string)$_POST['current'], setting('admin_password_hash'))) flash('Your current password is not right.');
            elseif ((string)$_POST['new'] !== '' && mb_strlen((string)$_POST['new']) < 10) flash('Use at least 10 characters for the new password.');
            else {
                $u = trim((string)($_POST['user'] ?? ''));
                if ($u !== '') set_setting('admin_user', $u);
                if ((string)$_POST['new'] !== '') set_setting('admin_password_hash', password_hash((string)$_POST['new'], PASSWORD_DEFAULT));
                flash('Sign-in details saved.');
            }
            redirect('/admin/settings#security');
        }
        if (!empty($_FILES['hero_image_file']) && $_FILES['hero_image_file']['error'] === UPLOAD_ERR_OK && $_FILES['hero_image_file']['size'] < 8 * 1024 * 1024) {
            $info = @getimagesize($_FILES['hero_image_file']['tmp_name']);
            $ext = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp'][$info['mime'] ?? ''] ?? null;
            if ($ext) {
                if (!is_dir(ROOT . '/uploads/pages')) mkdir(ROOT . '/uploads/pages', 0775, true);
                $name = 'homepage-' . date('Ymd') . '-' . bin2hex(random_bytes(3)) . '.' . $ext;
                move_uploaded_file($_FILES['hero_image_file']['tmp_name'], ROOT . "/uploads/pages/$name");
                $_POST['hero_image'] = "/uploads/pages/$name";
            }
        }
        $text = ['hero_set', 'hero_image', 'site_name', 'site_name_ja', 'site_url', 'support_email', 'orders_email', 'phone', 'announcement', 'announcement_link_text', 'announcement_link_url', 'min_order_usd', 'free_shipping_over_usd',
                 'shipping_standard_usd', 'shipping_express_usd', 'shipping_standard_label', 'shipping_express_label', 'hold_hours', 'countries_served', 'btc_address', 'other_payment_note', 'chat_code', 'head_code', 'default_currency'];
        foreach ($text as $k) if (isset($_POST[$k])) set_setting($k, trim((string)$_POST[$k]));
        if (isset($_POST['zone']) && is_array($_POST['zone'])) {
            $z = [];
            foreach (shipping_zones() as $zone => $old) { $in = $_POST['zone'][$zone] ?? []; $z[$zone] = array_map(fn($i) => is_numeric($in[$i] ?? null) ? max(0, round((float)$in[$i], 2)) : $old[$i], [0, 1, 2, 3]); }
            set_setting('shipping_zones', json_encode($z));
        }
        if (isset($_POST['rate'])) { $r = []; foreach ($_POST['rate'] as $c => $v) if (is_numeric($v) && $v > 0) $r[$c] = (float)$v; $r['USD'] = 1; set_setting('rates', json_encode($r)); set_setting('rates_updated', date('Y-m-d H:i') . ' (manual)'); }
        if (isset($_POST['rule'])) {
            $rules = [];
            foreach ($_POST['rule'] as $kind => $v) {
                $breaks = [];
                foreach (preg_split('/[,\s]+/', (string)$v['breaks']) as $b) if (preg_match('/^(\d+):([\d.]+)$/', $b, $m)) $breaks[] = [(int)$m[1], (float)$m[2]];
                $rules[$kind] = ['moq' => max(1, (int)$v['moq']), 'step' => max(1, (int)$v['step']), 'breaks' => $breaks];
                if ($kind === 'sealed') $rules[$kind]['max_price_for_moq'] = (float)$v['max'];
            }
            set_setting('pricing_rules', json_encode($rules));
        }
        flash('Settings saved.');
        redirect('/admin/settings' . (isset($_POST['_anchor']) ? '#' . preg_replace('/\W/', '', $_POST['_anchor']) : ''));
    }
    $s = fn($k) => h(setting($k));
    $rules = json_decode(setting('pricing_rules'), true);
    $rb = fn($kind) => implode(', ', array_map(fn($b) => $b[0] . ':' . $b[1], $rules[$kind]['breaks'] ?? []));
    ob_start(); ?>
<h1>Settings</h1>
<nav class="tabs small"><a href="#general">General</a><a href="#currency">Currencies</a><a href="#pricing">Pricing rules</a><a href="#shipping">Ordering &amp; shipping</a><a href="#payments">Payments</a><a href="#chat">Live chat &amp; Google</a><a href="#security">Password</a></nav>
