/* ------------------------------------------------------------------ tools */
// Brings the site content packed in this file into a shop that was installed with older content. Only replaces what has not
// been edited since installing (pages and category texts by their last-edit time, product descriptions marked automatic);
// orders, reviews, prices, stock and settings stay as they are, apart from a few default wordings nobody has changed.
const CONTENT_OLD_SETTINGS = [
    'announcement' => ['Free Standard shipping on orders over $2,000 âœ¦ Shipped tracked from Japan'],
    'other_payment_note' => ['We send your invoice and payment details to your email and phone within 12 hours, and hold your items for 48 hours.'],
    'tagline' => ['PokÃ©mon cards, English and Japanese, shipped from Japan to the USA and worldwide.'],
];
function content_update(): array {
    @set_time_limit(600);
    $file = DATA . '/packed-' . BUILD_ID . '.sqlite';
    if (!is_file($file)) {
        $packed = file_get_contents(__FILE__, false, null, __COMPILER_HALT_OFFSET__);
        $raw = $packed !== false ? gzdecode(ltrim($packed, "\r\n")) : false;
        unset($packed);
        if ($raw === false || $raw === '' || file_put_contents($file, $raw) === false) throw new RuntimeException('Could not unpack the new content. Upload index.php again in binary mode, then try once more.');
        unset($raw);
    }
    // Anything edited after installing (or after the last content update) is yours and stays.
    $now = gmdate('Y-m-d H:i:s');
    $cutoff = gmdate('Y-m-d H:i:s', max((int)filemtime(DATA . '/config.php'), (int)strtotime((setting('content_synced') ?: '1970-01-01') . ' UTC')) + 60);
    $pdo = db(); $pdo->exec('ATTACH DATABASE ' . $pdo->quote($file) . ' AS pk');
    $out = ['pages' => 0, 'new_pages' => 0, 'collections' => 0, 'alt' => 0, 'settings' => 0, 'descriptions' => 0, 'redirects' => 0, 'renamed' => 0, 'merged' => 0, 'kept' => []];
    $cols = fn(string $t, array $want) => array_values(array_intersect($want, array_column(all("PRAGMA main.table_info($t)"), 'name'), array_column(all("PRAGMA pk.table_info($t)"), 'name')));
    try {
        $pdo->beginTransaction();
        foreach (['pages' => ['title', 'h1', 'excerpt', 'body', 'seo_title', 'meta_desc', 'primary_kw'], 'collections' => ['h1', 'intro', 'body', 'seo_title', 'meta_desc', 'primary_kw']] as $t => $text) {
            $all = $cols($t, array_column(all("PRAGMA pk.table_info($t)"), 'name'));
            $all = array_values(array_diff($all, ['id', 'updated_at']));
            $text = $cols($t, $text);
            foreach (all("SELECT * FROM pk.$t") as $r) {
                $live = one("SELECT updated_at FROM main.$t WHERE path = ?", [$r['path']]);
                if (!$live) {
                    q("INSERT INTO main.$t(" . implode(',', $all) . ', updated_at) VALUES(' . str_repeat('?,', count($all)) . '?)', [...array_map(fn($c) => $r[$c], $all), $now]);
                    $out[$t === 'pages' ? 'new_pages' : 'collections']++;
                } elseif ((string)$live['updated_at'] > $cutoff) $out['kept'][] = $r['path'];
                else {
                    q("UPDATE main.$t SET " . implode(' = ?, ', $text) . ' = ?, updated_at = ? WHERE path = ?', [...array_map(fn($c) => $r[$c], $text), $now, $r['path']]);
                    $out[$t]++;
                }
            }
        }
        // photo descriptions still exactly as first supplied (checked against a fingerprint of the old text), never ones you wrote
        if (val("SELECT 1 FROM pk.sqlite_master WHERE name = 'prev_alt'")) {
            $set = $pdo->prepare('UPDATE main.products SET alt_text = ? WHERE id = ?');
            foreach (all('SELECT p.id, p.alt_text, k.alt_text new_alt, a.h FROM main.products p JOIN pk.prev_alt a ON a.id = p.id JOIN pk.products k ON k.id = p.id') as $r)
                if (substr(md5($r['alt_text']), 0, 16) === $r['h']) { $set->execute([$r['new_alt'], $r['id']]); $out['alt']++; }
        }
        // product addresses changed after your install: renamed, and the old address redirects to the new one
        $out['redirects'] = $pdo->exec('INSERT OR IGNORE INTO main.redirects(from_path, to_path, code) SELECT from_path, to_path, code FROM pk.redirects');
        $out['renamed'] = $pdo->exec("UPDATE main.products SET handle = (SELECT k.handle FROM pk.products k WHERE k.id = main.products.id)
            WHERE handle NOT IN (SELECT handle FROM pk.products)
              AND EXISTS (SELECT 1 FROM pk.products k JOIN pk.redirects r ON r.to_path = '/products/' || k.handle WHERE k.id = main.products.id AND r.from_path = '/products/' || main.products.handle)
              AND NOT EXISTS (SELECT 1 FROM main.products x WHERE x.handle = (SELECT k.handle FROM pk.products k WHERE k.id = main.products.id))");
        // listings merged into one after your install: hidden (never deleted), their old addresses redirect to the one that stays
        $out['merged'] = $pdo->exec("UPDATE main.products SET published = 0 WHERE published = 1 AND '/products/' || handle IN (SELECT from_path FROM pk.redirects) AND handle NOT IN (SELECT handle FROM pk.products)");
        // products that are the shop's own, with their photo served from this site
        $pdo->exec("UPDATE main.products SET source = 'manual', source_id = NULL WHERE source NOT IN ('cardbot', 'manual', 'import') AND handle IN (SELECT handle FROM pk.products WHERE source = 'manual')");
        $pdo->exec("UPDATE main.products SET image_url = (SELECT k.image_url FROM pk.products k WHERE k.handle = main.products.handle), image_local = (SELECT k.image_local FROM pk.products k WHERE k.handle = main.products.handle)
            WHERE image_local IN ('', '!') AND EXISTS (SELECT 1 FROM pk.products k WHERE k.handle = main.products.handle AND k.image_local LIKE 'assets/%')");
        foreach (CONTENT_OLD_SETTINGS as $key => $olds) {
            $new = (string)val('SELECT value FROM pk.settings WHERE key = ?', [$key]);
            if ($new !== '' && in_array(setting($key), $olds, true)) { set_setting($key, $new); $out['settings']++; }
        }
        set_setting('content_synced', $now);
        $pdo->commit();
    } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $pdo->exec('DETACH DATABASE pk'); throw $e; }
    $pdo->exec('DETACH DATABASE pk');
    @unlink($file);
    $out['descriptions'] = describe_fill(false);   // automatic descriptions, rewritten with this version's wording
    set_setting('content_version', CONTENT_VERSION);
    return $out;
}
function admin_tools(): void {
    if (is_post() && ($_POST['do'] ?? '') === 'content') {
        try {
            $r = content_update();
            flash(sprintf('Site content updated: %d pages refreshed and %d added, %d category and set pages, %d product descriptions, %d photo descriptions%s.', $r['pages'], $r['new_pages'], $r['collections'], $r['descriptions'], $r['alt'], $r['settings'] ? ", {$r['settings']} default wordings" : '')
                . ($r['renamed'] ? " {$r['renamed']} product addresses were renamed (the old ones redirect)." : '')
                . ($r['merged'] ? " {$r['merged']} duplicate listings were merged into the one that stays (hidden, not deleted; their old addresses redirect)." : '')
                . ($r['kept'] ? ' Kept as you edited them: ' . implode(', ', array_slice($r['kept'], 0, 12)) . (count($r['kept']) > 12 ? ' and ' . (count($r['kept']) - 12) . ' more' : '') . '.' : ''));
        } catch (Throwable $e) { flash('The update did not run: ' . $e->getMessage()); }
        redirect('/admin/tools');
    }
    if (is_post() && ($_POST['do'] ?? '') === 'rebuild') { $n = rebuild_all_paths(); flash("Re-linked $n products to their pages."); redirect('/admin/tools'); }
    if (is_post() && ($_POST['do'] ?? '') === 'describe') { @set_time_limit(300); $n = describe_fill(false); flash("Rewrote $n automatic descriptions. Descriptions you edited by hand were not touched."); redirect('/admin/tools'); }
    $remote = (int)val("SELECT COUNT(*) FROM products WHERE image_local = '' AND image_url != ''");
    $local = (int)val("SELECT COUNT(*) FROM products WHERE image_local NOT IN ('', '!')");
    ob_start(); ?>
