        for ($i = $from; $i <= $to; $i++) echo $i === $page ? "<span aria-current=\"page\">$i</span>" : '<a href="' . h(listing_url($base, $params, ['page' => $i])) . "\">$i</a>";
        if ($to < $pages) echo ($to < $pages - 1 ? '<span>â€¦</span>' : '') . '<a href="' . h(listing_url($base, $params, ['page' => $pages])) . "\">$pages</a>"; ?>
        <?php if ($page < $pages): ?><a href="<?= h(listing_url($base, $params, ['page' => $page + 1])) ?>" rel="next">Next â†’</a><?php endif ?>
      </nav>
