        <?php if ($img): ?><img src="<?= h($img) ?>" alt="<?= h($p['alt_text'] ?: $p['title']) ?>" width="600" height="600" fetchpriority="high"><?php else: ?><span class="muted small">Photo coming</span><?php endif ?>
      </div>
    </div>
    <div class="pdp-info">
      <div class="eyebrow gold"><?= h(implode(' Â· ', array_filter([$p['set_name'] ?: $p['section'], $p['language'] !== 'English' ? $p['language'] : '']))) ?></div>
