        <?php if ($p['compare_usd'] && $p['compare_usd'] > $p['price_usd']): ?><s class="mono muted"><?= money((float)$p['compare_usd']) ?></s><?php endif ?>
      </div>
      <?php if (count($lad['tiers']) > 1): ?>
      <table class="ladder" data-ladder='<?= h(json_encode(array_map(fn($t) => [$t[0], $t[1], money($t[1])], $lad['tiers']))) ?>'>
        <caption>Price per unit by quantity</caption>
        <tbody><?php foreach ($lad['tiers'] as $i => [$q, $u]): ?>
          <tr class="<?= $i === 0 ? 'is-active' : '' ?>"><td><?= $q ?><?= $i === count($lad['tiers']) - 1 ? '+' : '' ?></td><td><?= money($u) ?><?php if ($i): ?> <span class="muted small">âˆ’<?= round((1 - $u / $lad['tiers'][0][1]) * 100) ?>%</span><?php endif ?></td></tr>
        <?php endforeach ?></tbody>
      </table>
      <?php endif ?>

      <?php if ($p['in_stock']): ?>
      <form class="add add-pdp" data-add data-id="<?= (int)$p['id'] ?>" data-step="<?= $lad['step'] ?>" data-moq="<?= $lad['moq'] ?>" data-pdp>
        <div>
          <label class="small" for="pq">Quantity <span class="muted">Â· MOQ <?= $lad['moq'] ?><?= $lad['step'] > 1 ? ' Â· in ' . $lad['step'] . 's' : '' ?></span></label>
          <div class="qty qty-lg"><button type="button" data-dec aria-label="Fewer">âˆ’</button><input id="pq" type="number" inputmode="numeric" name="qty" value="<?= $lad['moq'] ?>" min="<?= $lad['moq'] ?>" step="<?= $lad['step'] ?>"><button type="button" data-inc aria-label="More">+</button></div>
        </div>
        <button class="btn btn-primary btn-lg" type="submit">Add to order Â· <span data-total><?= money($lad['tiers'][0][1] * $lad['moq']) ?></span></button>
      </form>
      <p class="note-ai small" data-nudge <?= count($lad['tiers']) > 1 ? '' : 'hidden' ?>><?php if (count($lad['tiers']) > 1): ?>Add <?= $lad['tiers'][1][0] - $lad['moq'] ?> more to pay <?= money($lad['tiers'][1][1]) ?> each.<?php endif ?></p>
      <?php else: ?>
      <p class="note-ai">Out of stock. <a href="/contact?product=<?= h(urlencode($p['title'])) ?>">Get a restock alert</a>.</p>
      <?php endif ?>
      <?php else: ?>
      <p class="pdp-price muted">Price on enquiry</p>
      <a class="btn btn-primary btn-lg" href="/contact?product=<?= h(urlencode($p['title'])) ?>">Ask about price</a>
      <?php endif ?>

      <dl class="facts"><?php foreach ($facts as $k => $v): ?><dt><?= h($k) ?></dt><dd><?= $v ?></dd><?php endforeach ?></dl>
    </div>
  </div>

  <?php if (trim(strip_tags($p['description']))): ?>
  <section class="section prose narrow"><h2 class="h2"><?= $p['section'] === 'Single Cards' ? 'About the card' : 'About the product' ?></h2><?= sanitize_html($p['description']) ?></section>
  <?php endif ?>

  <?php if (array_filter($explore)): ?>
  <nav class="section explore" aria-labelledby="ex-h">
    <h2 class="h2" id="ex-h">Explore more</h2>
    <div class="explore-cols">
      <?php foreach (['card' => $p['section'] === 'Single Cards' || str_contains($p['section'], 'Graded') ? 'More versions' : 'You might also like', 'set' => 'From the same set', 'learn' => 'Read before you buy'] as $k => $label): if (!$explore[$k]) continue; ?>
      <div><h3 class="h3"><?= h($label) ?></h3><ul><?php foreach ($explore[$k] as [$t, $u]): ?><li><a href="<?= h($u) ?>"><?= h($t) ?></a></li><?php endforeach ?></ul></div>
