    <div class="sec-head"><h2 class="h2">Customer reviews</h2><a href="/reviews">Read them all â†’</a></div>
    <div class="reviews-grid"><?php foreach ($reviews as $r) echo review_html($r, false); ?></div>
  </section>
  <?php endif ?>

  <?php if ($related): ?>
