    <div class="sec-head"><h2 class="h2"><?= $set ? 'More from ' . h($p['set_name']) : 'Goes well with' ?></h2><?php if ($set): ?><a href="<?= h($set['path']) ?>">See the whole set â†’</a><?php endif ?></div>
    <div class="grid"><?php foreach (array_slice($related, 0, 8) as $p) view__card(['p' => $p]); ?></div>
