.tag:before{content:"";width:6px;height:6px;background:currentColor}
.tag-stock{background:var(--matcha-soft);color:var(--matcha)}.tag-preorder{background:var(--ai-soft);color:var(--ai)}.tag-limited{background:var(--kin-soft);color:var(--kin)}
.input{width:100%;height:44px;padding:0 12px;background:var(--raised);border:1px solid var(--line-strong);border-radius:2px;color:var(--ink)}
textarea.input{height:auto;padding:10px 12px;line-height:22px}
select.input{appearance:auto}
.lattice{background-color:var(--sunken);background-image:linear-gradient(45deg,transparent calc(50% - .5px),var(--line) calc(50% - .5px),var(--line) calc(50% + .5px),transparent calc(50% + .5px)),linear-gradient(-45deg,transparent calc(50% - .5px),var(--line) calc(50% - .5px),var(--line) calc(50% + .5px),transparent calc(50% + .5px));background-size:32px 32px}
.panel-box{background:var(--raised);border:1px solid var(--line);border-radius:4px;padding:24px;margin:0 0 24px;min-width:0}
